-- stochastic-processes implementation for GaussianProcess
-- Assumptions: stochastic increments use the specified time step; physical SDE parameters use SI units and random draws are supplied or generated by the documented stream.
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Shared = ReplicatedStorage:WaitForChild("VectorForgeShared")
local Num = require(Shared:WaitForChild("NumericalKernels"))
local VectorForge = ReplicatedStorage:WaitForChild("VectorForge")
local LA = require(VectorForge:WaitForChild("SpectralLinearAlgebra"))

local Module = {}
function Module.Predict(trainX,trainY,testX,kernel,noiseVariance)
    assert(#trainX==#trainY and #trainX>0,"training dimensions mismatch"); Num.Nonnegative(noiseVariance,"observation noise")
    local n=#trainX; local Kxx=LA.Zeros(n,n)
    for i=1,n do for j=1,n do Kxx[i][j]=kernel(trainX[i],trainX[j]) end; Kxx[i][i]+=noiseVariance end
    local alpha,reason=LA.Solve(Kxx,trainY); assert(alpha,reason or "Gaussian process covariance singular")
    local means,variances={},{}
    for t=1,#testX do
        local k=table.create(n); for i=1,n do k[i]=kernel(trainX[i],testX[t]) end
        means[t]=LA.Dot(k,alpha)
        local solved=LA.Solve(Kxx,k); assert(solved,"GP covariance solve failed")
        variances[t]=math.max(0,kernel(testX[t],testX[t])-LA.Dot(k,solved))
    end
    return means,variances
end

return Module
